on conflict (id) do update set
  type = excluded.type, parent_id = excluded.parent_id, bashki_id = excluded.bashki_id, slug = excluded.slug,
  name = excluded.name, name_definite = excluded.name_definite, lat = excluded.lat, lng = excluded.lng,
  bbox = excluded.bbox, postal_code = excluded.postal_code, app_city = excluded.app_city,
  offered = excluded.offered, source = excluded.source, names = excluded.names;

